import 'package:flutter/material.dart';
import '../services/local_store.dart';
class DashboardPage extends StatefulWidget { const DashboardPage({super.key}); @override State<DashboardPage> createState()=>_DashboardPageState(); }
class _DashboardPageState extends State<DashboardPage>{int fields=0,scans=0,attention=0;@override void initState(){super.initState();load();}Future<void>load()async{final f=await LocalStore.getFields();final r=await LocalStore.getReports();if(mounted)setState((){fields=f.length;scans=r.length;attention=r.where((x)=>x['healthStatus']!='Healthy').length;});}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Crop Health Dashboard',style:TextStyle(fontWeight:FontWeight.w700)),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:_Stat(title:'Fields',value:fields.toString(),icon:Icons.agriculture_outlined)),const SizedBox(width:10),Expanded(child:_Stat(title:'Scans',value:scans.toString(),icon:Icons.camera_alt_outlined)),const SizedBox(width:10),Expanded(child:_Stat(title:'Attention',value:attention.toString(),icon:Icons.warning_amber_rounded))]),const SizedBox(height:18),const Card(child:Padding(padding:EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('About this dashboard',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),SizedBox(height:8),Text('These are activity indicators from your saved fields and scans. They are not a scientific crop-health score.')])))]));}
class _Stat extends StatelessWidget{final String title,value;final IconData icon;const _Stat({required this.title,required this.value,required this.icon});@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(children:[Icon(icon,color:const Color(0xFF1D6B43)),const SizedBox(height:7),Text(value,style:const TextStyle(fontSize:25,fontWeight:FontWeight.w800)),Text(title,style:const TextStyle(fontSize:12))])));}
